// cn() for the whole app: joins class names and resolves Tailwind conflicts
// (the later class wins). It is the cn package, taught the project's own
// theme so overrides work (AGENTS.md section 7):
// - the control sizes from index.css (h-control, size-control-sm, ...)
// - the type-* text roles, which set font size, line height and family
// shadcn components generated by the CLI import cn from "cn"; change their
// import to "@/lib/utils" when adding them.
import { createCn } from "cn/config";

const TYPE_ROLES = [
    "display",
    "page-title",
    "section-title",
    "card-title",
    "body",
    "small",
    "caption",
];

export const cn = createCn({
    extend: {
        theme: {
            spacing: ["control", "control-sm", "control-lg", "control-touch"],
        },
        classGroups: {
            "type-role": [{ type: TYPE_ROLES }],
        },
        conflictingClassGroups: {
            "type-role": ["font-size", "leading", "font-family"],
            "font-size": ["type-role"],
        },
    },
});
